class Solution:
    def matrixSumQueries(self, n: int, queries: List[List[int]]) -> int:
        rows, cols, ans = set(), set(), 0
        for t, i, v in reversed(queries):
            if t == 0 and i not in rows:
                ans += v * (n - len(cols)); rows.add(i)
            elif t == 1 and i not in cols:
                ans += v * (n - len(rows)); cols.add(i)
        return ans

