class Solution {
public:
    long long matrixSumQueries(int n, vector<vector<int>>& queries) {
        unordered_set<int> rows, cols;
        long long ans = 0;
        for (int q = queries.size() - 1; q >= 0; --q) {
            int t = queries[q][0], i = queries[q][1], v = queries[q][2];
            if (t == 0 && !rows.count(i)) { ans += (long long)v * (n - cols.size()); rows.insert(i); }
            else if (t == 1 && !cols.count(i)) { ans += (long long)v * (n - rows.size()); cols.insert(i); }
        }
        return ans;
    }
};

