class Solution {
    public long matrixSumQueries(int n, int[][] queries) {
        Set<Integer> rows = new HashSet<>(), cols = new HashSet<>();
        long ans = 0;
        for (int q = queries.length - 1; q >= 0; q--) {
            int t = queries[q][0], i = queries[q][1], v = queries[q][2];
            if (t == 0 && !rows.contains(i)) { ans += (long) v * (n - cols.size()); rows.add(i); }
            else if (t == 1 && !cols.contains(i)) { ans += (long) v * (n - rows.size()); cols.add(i); }
        }
        return ans;
    }
}

