var matrixSumQueries = function(n, queries) {
    const rows = new Set(), cols = new Set();
    let ans = 0;
    for (let q = queries.length - 1; q >= 0; q--) {
        const [t, i, v] = queries[q];
        if (t === 0 && !rows.has(i)) { ans += v * (n - cols.size); rows.add(i); }
        else if (t === 1 && !cols.has(i)) { ans += v * (n - rows.size); cols.add(i); }
    }
    return ans;
};
